def run(context):
    portfolio, sector_changes = context
    risk_report = {
        'high_risk': [],
        'low_risk': []
    }
    for holding in portfolio:
        symbol = holding['symbol']
        if sector_changes[symbol]['change_1m_pct'] < -5:
            risk_report['high_risk'].append(symbol)
        else:
            risk_report['low_risk'].append(symbol)
    return [risk_report]

def run(context):
    evidence = []
    for stock in context.get('stocks', []):
        symbol = stock.get('symbol')
        if symbol:
            evidence.append({'symbol': symbol, 'insight': 'Potential breakout with strong fundamentals'})
    return evidence

def run(context):
    symbols = context.get('selected_symbols', [])
    if not symbols:
        return {}
    return {'narrative': 'Narrative insights based on selected symbols.'}
